        numberInQuran: 2593,
        juz: 17,
        page: 331,
        arab: "\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0627\u0644\u0652\u062c\u064e\u0647\u0652\u0631\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u0650 \u0648\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0646\u064e",
